// rtm-dual (require condition): a genuinely DIFFERENT implementation of
// `entry` than esm.mjs — different table, constants, and prefix — so the
// import/require divergence is observable, not cosmetic. Never loaded at
// runtime in the garden (the app imports via ESM), but the analyzer's
// createRequire().resolve() lands here.
'use strict';

function entry(seed) {
  const table = ['girder', 'truss', 'rivet', 'gusset', 'strut'];
  const text = String(seed);
  let acc = 79;
  for (let i = 0; i < text.length; i++) {
    acc = (acc * 127 + text.charCodeAt(i) * (i + 5)) % 8779;
  }
  const tag = table[acc % table.length];
  const lower = text.toLowerCase();
  return 'rtm-dual:cjs:entry:' + tag + ':' + acc + ':' + lower;
}
exports.entry = entry;
